<script setup lang="ts">
import { computed } from 'vue';
import { router } from '@inertiajs/vue3';
import MemberLayout from '../../Layouts/MemberLayout.vue';
import { Activity, CalendarDays, Gauge, Medal, MessageCircle, Ruler, Scale, Sparkles, TrendingDown, TrendingUp, Volleyball } from '@lucide/vue';
type Assessment={id:number;date:string;height_cm:number|null;weight_kg:number|null;standing_reach_cm:number|null;vertical_jump_cm:number|null;spike_reach_cm:number|null;block_reach_cm:number|null;agility_seconds:number|null;coach_notes:string|null;recorder:string|null};
type Athlete={id:number;name:string;membership_number:string;team:string|null;position:string|null;jersey_number:number|null;photo_url:string|null};
type Profile={id:number;name:string;photo_url:string|null};
const props=defineProps<{athlete:Athlete|null;assessments:Assessment[];progress:Record<string,number|null>;viewer:{mode:string};profiles:Profile[]}>();
const latest=computed(()=>props.assessments[0]||null); const isGuardian=computed(()=>props.viewer.mode==='guardian');
const selectProfile=(id:number)=>router.get('/my-performance',{athlete:id},{preserveState:false});
const dateLabel=(value:string)=>new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${value}T12:00:00`));
const change=(key:string,reverse=false)=>{const value=props.progress[key];if(value==null)return null;return {value:`${value>0?'+':''}${value}`,good:reverse?value<0:value>0};};
const barHeight=(value:number|null)=>{if(!value)return '8%';const values=props.assessments.map(i=>i.vertical_jump_cm||0);const min=Math.min(...values),max=Math.max(...values);return `${28+((value-min)/Math.max(1,max-min))*68}%`;};
const metrics=computed(()=>latest.value?[{key:'height_cm',label:'قد',unit:'cm',icon:Ruler,value:latest.value.height_cm},{key:'weight_kg',label:'وزن',unit:'kg',icon:Scale,value:latest.value.weight_kg},{key:'vertical_jump_cm',label:'پرش عمودی',unit:'cm',icon:TrendingUp,value:latest.value.vertical_jump_cm},{key:'standing_reach_cm',label:'دسترسی ایستاده',unit:'cm',icon:Gauge,value:latest.value.standing_reach_cm},{key:'spike_reach_cm',label:'دسترسی اسپک',unit:'cm',icon:Volleyball,value:latest.value.spike_reach_cm},{key:'block_reach_cm',label:'دسترسی دفاع',unit:'cm',icon:Medal,value:latest.value.block_reach_cm},{key:'agility_seconds',label:'چابکی',unit:'ثانیه',icon:TrendingDown,value:latest.value.agility_seconds}]:[]);
</script>
<template><MemberLayout title="رکوردها و پیشرفت" :athlete-id="athlete?.id">
<section v-if="!athlete" class="member-empty"><Activity :size="36"/><h2>هنوز رکوردی برای نمایش نداریم</h2><p>پس از اتصال پرونده و ثبت اولین ارزیابی توسط مربی، روند پیشرفت اینجا نمایش داده می‌شود.</p></section>
<template v-else>
<section v-if="isGuardian&&profiles.length>1" class="member-profile-switch"><span>پیشرفت کدام ورزشکار؟</span><button v-for="profile in profiles" :key="profile.id" :class="profile.id===athlete.id?'active':''" @click="selectProfile(profile.id)"><img v-if="profile.photo_url" :src="profile.photo_url"><span v-else>{{profile.name.slice(0,1)}}</span>{{profile.name}}</button></section>
<header class="member-performance-hero"><div class="member-performance-person"><div><img v-if="athlete.photo_url" :src="athlete.photo_url"><span v-else>{{athlete.name.slice(0,2)}}</span></div><section><small>پاسپورت عملکرد</small><h1>{{athlete.name}}</h1><p>{{athlete.team||'بدون تیم'}}<template v-if="athlete.position"> · {{athlete.position}}</template><template v-if="athlete.jersey_number"> · شماره {{athlete.jersey_number}}</template></p></section></div><div v-if="latest" class="member-last-test"><CalendarDays :size="18"/><span>آخرین ارزیابی<strong>{{dateLabel(latest.date)}}</strong></span></div></header>
<template v-if="latest">
<section class="member-highlight"><div><Sparkles :size="20"/><span>رکورد شاخص</span><h2>{{latest.vertical_jump_cm??'—'}} <small>سانتی‌متر پرش عمودی</small></h2></div><p v-if="change('vertical_jump_cm')" :class="change('vertical_jump_cm')?.good?'good':'neutral'"><TrendingUp :size="17"/>{{change('vertical_jump_cm')?.value}} سانتی‌متر نسبت به ارزیابی قبل</p><p v-else class="neutral">برای مقایسه، یک ارزیابی دیگر لازم است.</p></section>
<section class="member-performance-grid"><article v-for="metric in metrics" :key="metric.key"><span><component :is="metric.icon" :size="18"/></span><small>{{metric.label}}</small><strong>{{metric.value??'—'}} <em>{{metric.unit}}</em></strong><i v-if="change(metric.key,metric.key==='agility_seconds')" :class="change(metric.key,metric.key==='agility_seconds')?.good?'good':''">{{change(metric.key,metric.key==='agility_seconds')?.value}}</i><i v-else>اولین رکورد</i></article></section>
<div class="member-performance-panels"><section class="member-chart-card"><header><div><span>روند پیشرفت</span><h2>پرش عمودی در طول زمان</h2></div><strong>{{assessments.length}} ارزیابی</strong></header><div class="member-chart"><div v-for="item in [...assessments].reverse()" :key="item.id"><strong>{{item.vertical_jump_cm??'—'}}</strong><i :style="{height:barHeight(item.vertical_jump_cm)}"/><span>{{new Intl.DateTimeFormat('fa-IR',{month:'short',year:'2-digit'}).format(new Date(`${item.date}T12:00:00`))}}</span></div></div></section><section class="member-coach-note"><MessageCircle :size="24"/><span>یادداشت مربی {{latest.recorder||''}}</span><p>{{latest.coach_notes||'با استمرار در تمرین‌ها، رکوردهای بعدی مسیر پیشرفت را دقیق‌تر نشان می‌دهند.'}}</p></section></div>
<section class="member-history"><header><div><span>تاریخچه ارزیابی</span><h2>مسیر رکوردهای من</h2></div></header><article v-for="item in assessments" :key="item.id"><div class="member-history-date"><CalendarDays :size="16"/><span>{{dateLabel(item.date)}}</span></div><div><span>پرش<strong>{{item.vertical_jump_cm??'—'}} cm</strong></span><span>اسپک<strong>{{item.spike_reach_cm??'—'}} cm</strong></span><span>دفاع<strong>{{item.block_reach_cm??'—'}} cm</strong></span><span>چابکی<strong>{{item.agility_seconds??'—'}} s</strong></span></div></article></section>
</template><section v-else class="member-empty compact"><Activity :size="30"/><h2>اولین ارزیابی هنوز ثبت نشده</h2><p>مربی پس از رکوردگیری قد، پرش، اسپک، دفاع و چابکی، نتیجه را در این صفحه ثبت می‌کند.</p></section>
</template></MemberLayout></template>
